<?php
/**
 * Plugin Name: ARBICOP shared header/footer (shop)
 * Description: The shop (/tienda) renders the SAME header and footer as the root site. Their Elementor data lives in
 *              the shop's templates #20 (header) and #23 (footer), generated by docker/header-footer/build.py from the
 *              root home page. The root site's Elementor kit differs from the shop's kit (global colors/typography,
 *              container width, container padding, widget spacing), so those kit variables are re-declared in
 *              arbicop-shared-header.css, scoped to the header/footer locations only: shop pages are not affected.
 */
add_action('wp_head', function () {
    $css = @file_get_contents(__DIR__ . '/arbicop-shared-header.css');
    if ($css) echo '<style id="arbicop-shared-header">' . $css . '</style>';
}, 99);
